mapper.select:
SELECT id, trip_plan_id, attraction_id, name, latitude, longitude,
       visit_day, order_index, memo, created_at, updated_at
  FROM trip_places
 WHERE trip_plan_id = #{planId}
   AND visit_day = #{visitDay}
 ORDER BY order_index ASC, id ASC

SELECT id, trip_plan_id, attraction_id, name, latitude, longitude,
       visit_day, order_index, memo, created_at, updated_at
  FROM trip_places
 WHERE id = #{id}
   AND trip_plan_id = #{planId}

SELECT COALESCE(MAX(order_index), 0)
  FROM trip_places
 WHERE trip_plan_id = #{planId}
   AND (
        (#{visitDay} IS NULL AND visit_day IS NULL)
        OR visit_day = #{visitDay}
   )

mapper.update:
UPDATE trip_places
   SET visit_day = #{visitDay},
       order_index = #{orderIndex}
 WHERE id = #{id}
   AND trip_plan_id = #{planId}

UPDATE trip_places
   SET order_index = #{orderIndex}
 WHERE id = #{id}
   AND trip_plan_id = #{planId}

mapper.delete:
DELETE FROM trip_places
 WHERE id = #{id}
   AND trip_plan_id = #{planId}
